//! Raw bounded V15 coupled SSPRK / gas-midpoint histories. No order admission.
//! MD14 dt_seed=1e16 s is an initial packet construction, not elapsed history.
use rei_microphysics::{axbi_driver::{Driver,DriverConfig,DriverState,SourceClockConfig,SourcePlacement,NativeClockMode,PhysicalBirthRule,BirthMicroSegment,SsprkStageDiagnostics},axbi_covariant_transport::PhotonAttenuation,igm_state::{IgmGasState,w_erg_per_h_to_ev},igm_thermal::IgmPointRhs,HHeModel,Absorber,AtomicProvider};
use std::{fs::File,io::{Write,BufWriter},time::Instant};
type R<T>=Result<T,String>;
fn initial(seed:bool)->R<(Driver,DriverState,f64)>{let mut c=DriverConfig::baseline();c.transport_cells=16;c.transport_threads=1;c.background_panels=128;let(mut d,mut s)=Driver::new(c).map_err(|e|format!("driver {e:?}"))?;let nh=d.n_h0_cm3/s.a.powi(3);let nhe=d.n_he0_cm3/s.a.powi(3);s.gas=IgmGasState::from_temperature([0.075,0.12,0.03],nh,nhe,15000.).map_err(|e|format!("gas {e:?}"))?;let g=d.geometry_point(s.a).and_then(|p|p.geometry()).map_err(|e|format!("geometry {e:?}"))?;
if seed{let mut p=d.transport.empty_state();let l=d.transport.inject(&mut p,&g,20.,1e16).map_err(|e|format!("seed {e:?}"))?;s.photons=p.number;s.photon_energy_ref=p.energy_ref;s.photon_support_lo=p.support_lo;s.photon_support_hi=p.support_hi;s.ledgers.source_n=l.added_photons_per_h;s.ledgers.source_u=l.added_energy_ev_per_h;}
d.set_source_clocks(&s,SourceClockConfig{microphysics:NativeClockMode::AllMid,opacity_midpoint:true,source:SourcePlacement::Disabled,attenuation:PhotonAttenuation::Exponential,nonlinear_tolerance:1e-15}).map_err(|e|format!("clocks {e:?}"))?;
let ap=AtomicProvider::reference();let abs=[nh*0.925,nhe*0.85,nhe*0.12];let mut opacity=0.;for j in 0..3{opacity+=abs[j]*ap.cross_section([Absorber::HI,Absorber::HeI,Absorber::HeII][j],20.).map_err(|e|format!("sigma {e:?}"))?;}Ok((d,s,HHeModel::controlled_fixture().c_cm_s*opacity))}
#[derive(Default)]struct Totals{time_s:f64,p:[f64;3],ci:[f64;3],rr:[f64;3],dr:f64,b:f64,q:f64,ce:[f64;3],rrdr:[f64;4],ff:f64,cmb:f64,escape:f64}
impl Totals{
fn segment(&mut self,r:&BirthMicroSegment){self.time_s+=r.dt_s;for j in 0..3{self.p[j]+=r.photo_events_per_h[j];self.ci[j]+=r.ci_events_per_h[j];self.rr[j]+=r.rr_events_per_h[j];self.ce[j]+=r.ce_cooling_ev_per_h[j];}for j in 0..4{self.rrdr[j]+=r.rrdr_cooling_ev_per_h[j];}self.dr+=r.dr_events_per_h;self.b+=r.photo_binding_ev_per_h;self.q+=r.photo_heat_ev_per_h;self.ff+=r.ff_cooling_ev_per_h;self.cmb+=r.cmb_input_ev_per_h;self.escape+=r.escaped_ev_per_h;}
fn rhs(&mut self,r:IgmPointRhs,nh:f64,dt:f64)->BirthMicroSegment{let e=dt/nh;let u=e/HHeModel::controlled_fixture().ev_erg;let ph=r.photo_events_cm3_s.map(|v|v*e);let b=(0..3).map(|j|ph[j]*HHeModel::controlled_fixture().threshold_ev[j]).sum();let rr=r.rr_thermal_sink_erg_cm3_s.map(|v|v*u);let segment=BirthMicroSegment{a_begin:0.,a_mid:0.,a_end:0.,dt_s:dt,n_h_cm3:nh,photo_events_per_h:ph,ci_events_per_h:r.ci_events_cm3_s.map(|v|v*e),rr_events_per_h:r.rr_events_cm3_s.map(|v|v*e),dr_events_per_h:r.dr_events_cm3_s*e,photo_binding_ev_per_h:b,photo_heat_ev_per_h:r.photo_input_erg_cm3_s*u-b,ce_cooling_ev_per_h:r.ce_thermal_sink_erg_cm3_s.map(|v|v*u),rrdr_cooling_ev_per_h:[rr[0],rr[1],rr[2],r.dr_thermal_sink_erg_cm3_s*u],ff_cooling_ev_per_h:r.freefree_thermal_sink_erg_cm3_s*u,cmb_input_ev_per_h:r.cmb_to_gas_erg_cm3_s*u,escaped_ev_per_h:r.escape_erg_cm3_s*u};self.segment(&segment);segment}
}
fn binding(d:&Driver,s:&DriverState)->f64{let t=HHeModel::controlled_fixture().threshold_ev;let[x,y,z]=s.gas.fractions;t[0]*x+d.n_he0_cm3/d.n_h0_cm3*(t[1]*y+(t[1]+t[2])*z)}
fn states(d:&Driver,s:&DriverState)->R<Vec<f64>>{let nh=d.n_h0_cm3/s.a.powi(3);let nhe=d.n_he0_cm3/s.a.powi(3);let eos=s.gas.eos(nh,nhe).map_err(|e|format!("eos {e:?}"))?;let pool=d.photon_pool_inventory(s).map_err(|e|format!("pool {e:?}"))?;let w=w_erg_per_h_to_ev(s.gas.w_erg_per_h).map_err(|e|format!("w {e:?}"))?;let b=binding(d,s);let mut v=vec![s.a,s.gas.fractions[0],s.gas.fractions[1],s.gas.fractions[2],s.gas.w_erg_per_h,w,b,eos.electron_density_cm3/nh,eos.temperature_k];v.extend(pool);Ok(v)}
const STATE_FIELDS:&str="a,HII,HeII,HeIII,w_erg_H,w_eV_H,binding_eV_H,electrons_H,T_K,active_N,active_U,passive_N,passive_U";
#[allow(clippy::too_many_arguments)]
fn row(w:&mut BufWriter<File>,header:&mut bool,d:&Driver,s:&DriverState,before:&DriverState,t:&Totals,st:&SsprkStageDiagnostics,kind:&str,m:usize,step:usize,kref:f64,dt:f64,elapsed:f64)->R<()>{
let iv=states(d,before)?;let fv=states(d,s)?;let mut fields:Vec<String>="m,step,unique_history,prefix_repeat,is_final,k_ref20_s_inv,dt_s,total_time_s,Xend_target,actual_X,actual_X_minus_target,cells,threads,background_panels,nonlinear_tolerance,seed_dt_s,initial_seed_N,initial_seed_U,physical_c".split(',').map(str::to_owned).collect();let target=if kind=="fixed_geometry"{0.}else{1e-5*step as f64/m as f64};let x=((s.a-before.a)/before.a).ln_1p();let mut vals=vec![m as f64,step as f64,1.,0.,if step==m{1.}else{0.},kref,dt,t.time_s,target,x,x-target,16.,1.,128.,1e-15,if before.ledgers.source_n>0.{1e16}else{0.},before.ledgers.source_n,before.ledgers.source_u,HHeModel::controlled_fixture().c_cm_s];
for(prefix,v)in[("initial",iv.clone()),("final",fv.clone())]{for f in STATE_FIELDS.split(','){fields.push(format!("{prefix}_{f}"));}vals.extend(v);}
for(prefix,arr)in[("P",t.p),("C",t.ci),("R",t.rr),("CE",t.ce)]{for j in 0..3{fields.push(format!("{prefix}_{j}"));}vals.extend(arr);}
fields.extend("D,photo_binding,photo_heat,RRDR_0,RRDR_1,RRDR_2,RRDR_3,FF,signed_CMB,escape,gaswork,photonwork,source_N,source_U,boundary_N,boundary_U,absorbed_N,solver_max_residual,max_tau_stage1,max_tau_stage2,nodes_stage1,nodes_stage2,quad_count_stage1,quad_count_stage2,quad_energy_stage1,quad_energy_stage2,rhs_calls,steps,attempts,wall_s".split(',').map(str::to_owned));
vals.extend([t.dr,t.b,t.q]);vals.extend(t.rrdr);vals.extend([t.ff,t.cmb,t.escape,s.ledgers.thermal_work,s.ledgers.photon_work,s.ledgers.source_n,s.ledgers.source_u,s.ledgers.boundary_n,s.ledgers.boundary_u,s.ledgers.absorbed_n,s.max_newton_residual,st.max_tau_stage1,st.max_tau_stage2,st.nodes_stage1 as f64,st.nodes_stage2 as f64,st.quad_count_stage1,st.quad_count_stage2,st.quad_energy_stage1,st.quad_energy_stage2,s.rhs_evaluations as f64,s.accepted as f64,s.attempts as f64,elapsed]);
let ratio=d.n_he0_cm3/d.n_h0_cm3;let net: [f64;3]=std::array::from_fn(|j|t.p[j]+t.ci[j]-t.rr[j]);let ion1=net[1]-t.dr;let n=fv[9]+fv[11];let u=fv[10]+fv[12];let n0=iv[9]+iv[11];let u0=iv[10]+iv[12];let ci_bind=(0..3).map(|j|t.ci[j]*HHeModel::controlled_fixture().threshold_ev[j]).sum::<f64>();let capture=(0..3).map(|j|t.rr[j]*HHeModel::controlled_fixture().threshold_ev[j]).sum::<f64>()+t.dr*HHeModel::controlled_fixture().threshold_ev[1];let radiative=t.ce.iter().sum::<f64>()+t.rrdr.iter().sum::<f64>()+t.ff;
let raw_n=n+t.p.iter().sum::<f64>()+s.ledgers.boundary_n-s.ledgers.source_n;
let raw_energy=fv[5]-iv[5]+fv[6]-iv[6]+u-u0+t.escape+s.ledgers.boundary_u+s.ledgers.thermal_work+s.ledgers.photon_work-(s.ledgers.source_u-before.ledgers.source_u)-t.cmb;
let(nr,er)=d.residuals(s).map_err(|e|format!("residual {e:?}"))?;
fields.extend("audit_HII,audit_HeII,audit_HeIII,audit_electrons,audit_photo_binding,audit_binding,audit_thermal,audit_escape,audit_photon_N,audit_photon_U,audit_full_energy,owner_photon_residual,owner_energy_residual,initial_photon_N_recomputed,initial_photon_U_recomputed".split(',').map(str::to_owned));
vals.extend([fv[1]-iv[1]-net[0],ratio*(fv[2]-iv[2])-(ion1-net[2]),ratio*(fv[3]-iv[3])-net[2],fv[7]-iv[7]-net[0]-ion1-net[2],t.b-(0..3).map(|j|t.p[j]*HHeModel::controlled_fixture().threshold_ev[j]).sum::<f64>(),fv[6]-iv[6]-t.b-ci_bind+capture,fv[5]-iv[5]-t.q+ci_bind+radiative-t.cmb+s.ledgers.thermal_work,t.escape-capture-radiative,raw_n,u-u0+t.b+t.q+s.ledgers.photon_work+s.ledgers.boundary_u-(s.ledgers.source_u-before.ledgers.source_u),raw_energy,nr,er,n0,u0]);
if fields.len()!=vals.len(){return Err(format!("CSV shape {} {}",fields.len(),vals.len()));}if !vals.iter().all(|v|v.is_finite()){return Err("nonfinite CSV".into());}
if !*header{writeln!(w,"kind,{}",fields.join(",")).map_err(|e|e.to_string())?;*header=true;}write!(w,"{kind}").map_err(|e|e.to_string())?;for v in vals{write!(w,",{v:.17e}").map_err(|e|e.to_string())?;}writeln!(w).map_err(|e|e.to_string())?;w.flush().map_err(|e|e.to_string())?;Ok(())}
fn segment_row(w:&mut BufWriter<File>,kind:&str,m:usize,step:usize,j:usize,r:&BirthMicroSegment)->R<()>{let mut v=vec![r.a_begin,r.a_mid,r.a_end,r.dt_s,r.n_h_cm3];v.extend(r.photo_events_per_h);v.extend(r.ci_events_per_h);v.extend(r.rr_events_per_h);v.extend([r.dr_events_per_h,r.photo_binding_ev_per_h,r.photo_heat_ev_per_h]);v.extend(r.ce_cooling_ev_per_h);v.extend(r.rrdr_cooling_ev_per_h);v.extend([r.ff_cooling_ev_per_h,r.cmb_input_ev_per_h,r.escaped_ev_per_h]);write!(w,"{kind},{m},{step},{j}").map_err(|e|e.to_string())?;for x in v{write!(w,",{x:.17e}").map_err(|e|e.to_string())?;}writeln!(w).map_err(|e|e.to_string())?;Ok(())}
fn main()->R<()>{let args:Vec<String>=std::env::args().collect();if args.len()!=3{return Err("usage output.csv fixed|birth".into());}let mode=&args[2];if mode!="fixed"&&mode!="birth"{return Err("mode".into());}let clock=Instant::now();let mut w=BufWriter::new(File::create(&args[1]).map_err(|e|e.to_string())?);let mut bw=BufWriter::new(File::create(format!("{}.births.csv",args[1])).map_err(|e|e.to_string())?);let mut sw=BufWriter::new(File::create(format!("{}.segments.csv",args[1])).map_err(|e|e.to_string())?);let mut cw=BufWriter::new(File::create(format!("{}.cells.csv",args[1])).map_err(|e|e.to_string())?);let mut header=false;
writeln!(bw,"kind,m,step,node,a,weight_dln_a,proper_time_weight_s,added_N,added_U").map_err(|e|e.to_string())?;writeln!(sw,"kind,m,step,segment,a_begin,a_mid,a_end,dt_s,nh,P0,P1,P2,C0,C1,C2,R0,R1,R2,D,photoB,photoQ,CE0,CE1,CE2,RR0,RR1,RR2,DR,FF,CMB,escape").map_err(|e|e.to_string())?;writeln!(cw,"kind,m,cell,initial_N,final_N,delta_N,initial_Uref,final_Uref,delta_Uref,lo,hi").map_err(|e|e.to_string())?;
let kinds:Vec<(&str,bool,Option<PhysicalBirthRule>)>=if mode=="fixed"{vec![("fixed_geometry",true,None)]}else{vec![("physical_gl2",false,Some(PhysicalBirthRule::Gauss2)),("seeded_disabled_gl2",true,Some(PhysicalBirthRule::DisabledGauss2))]};
for(kind,seed,rule)in kinds{let levels:Vec<usize>=if mode=="fixed"{vec![8,16,32,64,128,256]}else{vec![32,64,128,256,512]};for m in levels{let(d,mut s,kref)=initial(seed)?;let before=s.clone();let mut t=Totals::default();let mut stages=SsprkStageDiagnostics::default();let mut counter=0;let runclock=Instant::now();eprintln!("START kind={kind} m={m} seed_N={:.17e} seed_U={:.17e} k_ref20={kref:.17e} tolerance=1e-15",s.ledgers.source_n,s.ledgers.source_u);
for step in 1..=m{let dt;
if let Some(rule)=rule{let target=before.a*(step as f64*1e-5/m as f64).exp();let dx=((target-s.a)/s.a).ln_1p();let r=d.fixed_step_physical_birth_ssprk2(&mut s,dx,rule).map_err(|e|format!("kind={kind} m={m} step={step} dx={dx:.17e} {e:?}"))?;dt=r.birth.segments.iter().map(|v|v.dt_s).sum();for(j,b)in r.birth.births.iter().enumerate(){writeln!(bw,"{kind},{m},{step},{j},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e}",b.a,b.weight_dln_a,b.proper_time_weight_s,b.added_photons_per_h,b.added_energy_ev_per_h).map_err(|e|e.to_string())?;}for(j,seg)in r.birth.segments.iter().enumerate(){t.segment(seg);segment_row(&mut sw,kind,m,step,j,seg)?;}stages.max_tau_stage1=stages.max_tau_stage1.max(r.stages.max_tau_stage1);stages.max_tau_stage2=stages.max_tau_stage2.max(r.stages.max_tau_stage2);stages.nodes_stage1+=r.stages.nodes_stage1;stages.nodes_stage2+=r.stages.nodes_stage2;stages.quad_count_stage1=stages.quad_count_stage1.max(r.stages.quad_count_stage1);stages.quad_count_stage2=stages.quad_count_stage2.max(r.stages.quad_count_stage2);stages.quad_energy_stage1=stages.quad_energy_stage1.max(r.stages.quad_energy_stage1);stages.quad_energy_stage2=stages.quad_energy_stage2.max(r.stages.quad_energy_stage2);
}else{dt=1./(kref*m as f64);s.attempts+=1;let r=d.chemical_stage_ssprk2(&mut s,dt,&mut counter).map_err(|e|format!("kind={kind} m={m} step={step} dt={dt:.17e} {e:?}"))?;s.rhs_evaluations=counter;s.accepted+=1;let nh=d.n_h0_cm3/s.a.powi(3);let mut segment=t.rhs(r.rhs,nh,dt);segment.a_begin=s.a;segment.a_mid=s.a;segment.a_end=s.a;segment_row(&mut sw,kind,m,step,0,&segment)?;stages.include(&r.transport);}
row(&mut w,&mut header,&d,&s,&before,&t,&stages,kind,m,step,kref,dt,runclock.elapsed().as_secs_f64())?;bw.flush().map_err(|e|e.to_string())?;sw.flush().map_err(|e|e.to_string())?;}
for k in 0..s.photons.len(){writeln!(cw,"{kind},{m},{k},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e}",before.photons[k],s.photons[k],s.photons[k]-before.photons[k],before.photon_energy_ref[k],s.photon_energy_ref[k],s.photon_energy_ref[k]-before.photon_energy_ref[k],s.photon_support_lo[k],s.photon_support_hi[k]).map_err(|e|e.to_string())?;}cw.flush().map_err(|e|e.to_string())?;eprintln!("COMPLETE kind={kind} m={m} rhs={} max_residual={:.17e} max_tau1={:.17e} max_tau2={:.17e} wall_s={:.6}",s.rhs_evaluations,s.max_newton_residual,stages.max_tau_stage1,stages.max_tau_stage2,runclock.elapsed().as_secs_f64());}}
eprintln!("COMPLETE mode={mode} wall_s={:.6}",clock.elapsed().as_secs_f64());Ok(())}
